import{_ as l,a0 as s,w as i,s as p,I as a,x as e,a1 as n,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"充分利用你的下一次技术会议的 7 个技巧 | LCTT x X-CMD","titleTemplate":false,"description":"充分利用你的下一次技术会议的 7 个技巧 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"充分利用你的下一次技术会议的 7 个技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"充分利用你的下一次技术会议的 7 个技巧 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference","title":"充分利用你的下一次技术会议的 7 个技巧","tag":"202304","desc":""},"relativePath":"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference.md","filePath":"[post].md"}'),m={name:"202304/20230411.3 ⭐️⭐️ 7 tips to make the most of your next tech conference.md"};function f(h,t,u,x,b,T){const r=s("Link");return i(),p("div",null,[t[20]||(t[20]=a("h1",{id:"充分利用你的下一次技术会议的-7-个技巧",tabindex:"-1"},[e("充分利用你的下一次技术会议的 7 个技巧 "),a("a",{class:"header-anchor",href:"#充分利用你的下一次技术会议的-7-个技巧","aria-label":"Permalink to “充分利用你的下一次技术会议的 7 个技巧”"},"​")],-1)),t[21]||(t[21]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/27/074139chzhgld44l4dih4b.jpg",alt:""})],-1)),t[22]||(t[22]=a("blockquote",null,[a("p",null,"会议是科技行业的福利之一。以下是如何充分利用你所参加的会议的方法。")],-1)),a("p",null,[t[2]||(t[2]=e("我在 2023 年 2 月参加了两个针对开源软件的技术会议。我是比利时根特举办的 ",-1)),n(r,{href:"https://cfgmgmtcamp.eu/ghent2023/"},{default:o(()=>[...t[0]||(t[0]=[e("Config Management Camp",-1)])]),_:1}),t[3]||(t[3]=e(" 的演讲者，也是比利时布鲁塞尔 ",-1)),n(r,{href:"https://fosdem.org/2023/"},{default:o(()=>[...t[1]||(t[1]=[e("FOSDEM",-1)])]),_:1}),t[4]||(t[4]=e(" 的与会者。本文旨在着重讲述我在会议上的经验，并为你提供一些如何充分利用这种机会的建议。",-1))]),t[23]||(t[23]=d('<h3 id="保持目的性" tabindex="-1">保持目的性 <a class="header-anchor" href="#保持目的性" aria-label="Permalink to “保持目的性”">​</a></h3><p>不同的人参加会议有不同的原因。有些人是某个主题、知识或兴趣领域的演讲者。另外一些人是希望从这些讲座中获得知识并与其他志同道合的人建立联系的与会者。也有一些代表他们公司的与会者。你很可能属于其中的一类。明确你希望从会议中获得什么，这是进行一次成功会议访问的第一步。如果你是一个演讲者，这意味着你要熟练掌握你所演讲的东西。如果你是一个与会者，你应该对你想从会议中获得什么有一个认识。</p><h3 id="了解场地和会议日程" tabindex="-1">了解场地和会议日程 <a class="header-anchor" href="#了解场地和会议日程" aria-label="Permalink to “了解场地和会议日程”">​</a></h3><p>FOSDEM 是一个非常大的会议，在两天的时间里至少有六千人参加。对于一个参加这样一个大型的会议的与会者来说，由于许多演讲会在同一时间举行，无法参加所有你感兴趣的会议并不奇怪。通常，这样的大型会议在大学或会议中心等宽敞的场地举行。由于面积非常大，会议会根据特定的主题分散在整个会场。这些会议会有一个固定的日程，所以有时你可能必须迅速地从场地的一边跑到另一边。场馆地图可以在场馆网站上轻松获取。在第一天早点到达会场并熟悉它是非常有用的。这有助于节省你在一个演讲结束时匆忙赶往另一个演讲的时间。</p><h3 id="记些笔记" tabindex="-1">记些笔记 <a class="header-anchor" href="#记些笔记" aria-label="Permalink to “记些笔记”">​</a></h3><p>在现场集中注意力和专注于演讲当然很好。然而，你的头脑只能记住这么多。当然，有些人会试着尽可能地利用他们的手机拍摄正在演示的幻灯片（顺着演讲者的演讲节奏）。如果你想在社交媒体上快速更新你正在参加的会议信息，这是很好的。但是它不是很有效的笔记。通常幻灯片上的有效信息是最少的。但是如果演讲者在台上深入地解释了一些东西，你可能会错过这些解释。我建议你随身携带一个记事本和一支笔。你甚至可以带上笔记本电脑做笔记。这个做法的目的是在于通过在演讲中对有趣的花絮做一个简短的笔记，以便你可以在以后重温它们。而且它让你总是能在演讲快结束时回想起要向演讲者提问的问题。</p><h3 id="建立关系和促成协作" tabindex="-1">建立关系和促成协作 <a class="header-anchor" href="#建立关系和促成协作" aria-label="Permalink to “建立关系和促成协作”">​</a></h3><p>会议可能是与志同道合的人彼此交往的最佳场所。他们和你一样对同样的话题感兴趣。最好利用这段时间来了解在感兴趣的话题上正在发生什么，看看人们如何解决令人感兴趣的问题，他们如何处理事情，并掌握整个行业的脉搏。你在会议上的时间有限，所以一定要把你介绍给那些从事与你有关的工作的人。这是一个收集信息的好机会，以便以后与他们沟通。你可以通过电子邮件、Mastodon、领英等方式交换个人信息。</p><h3 id="腾出时间看展位和礼品" tabindex="-1">腾出时间看展位和礼品 <a class="header-anchor" href="#腾出时间看展位和礼品" aria-label="Permalink to “腾出时间看展位和礼品”">​</a></h3><p>大多数技术会议都有来自各种公司或上游项目的展位，希望推销他们的产品和服务。为了吸引更多参展的人，展位上经常会有各种各样的免费的礼品（在大多数情况下）。这些礼品通常是贴纸、凉水瓶、有趣的小玩意、毛绒玩具、笔之类。一定要把它们收集起来，这样你就有东西送给你的同事和朋友了。参观展位不应该只是为了礼品。你应该利用这个机会与来自不同公司的人交谈（即使他们是竞争对手），以了解他们能提供什么。谁没准你就会得到以后的项目知识！</p><h3 id="放松" tabindex="-1">放松 <a class="header-anchor" href="#放松" aria-label="Permalink to “放松”">​</a></h3><p>参加会议不应该只是为了工作。这也让你你从平时忙碌的日程中休息一下，放松一下。很有可能你正在前往一个你还没有访问过的不同的国家或城市。会议、会谈和技术讨论都很重要。但这只是整个体验的一部分。另一半的经验是旅行，它可以使人了解另一个国家、它的文化、它的人民、食物、语言和不同的生活方式。退一步讲，享受所有这些经历，留下终生的回忆。我建议你在住宿的地方找一些著名的地标兼做。你也应该尝试当地的美食，或者你可以和当地人聊天。最后，你会发现你认为从来没有存在过的自己的另一面。</p><h3 id="写下你的经历" tabindex="-1">写下你的经历 <a class="header-anchor" href="#写下你的经历" aria-label="Permalink to “写下你的经历”">​</a></h3><p>一旦你从会议回来，不要只是忘记它然后回到你的日常生活，就好像什么都没发生一样。利用这个机会写下你的经历，并分享你认为最好的演讲以及原因。会议和旅行的主要收获是什么？你应该记录你学到的东西。你应该主动联系你在会议上遇到的人。你也可以在社交媒体上关注你可能错过的事情。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>会议是科技行业的福利之一。我建议每个人在职业生涯中的某个时候都去一次。我希望这篇文章能帮助你了解如何在参加技术会议时最大限度地利用会议。</p><p><em>（题图：MJ/conference illustration talk meetup in high resolution, very detailed, 8k）</em></p><hr>',18)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),n(r,{href:"https://opensource.com/article/23/4/tips-tech-conference"},{default:o(()=>[...t[5]||(t[5]=[e("https://opensource.com/article/23/4/tips-tech-conference",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),n(r,{href:"https://opensource.com/users/gkamathe"},{default:o(()=>[...t[7]||(t[7]=[e("Gaurav Kamathe",-1)])]),_:1}),t[12]||(t[12]=e(" 选题：",-1)),n(r,{href:"https://github.com/lkxed/"},{default:o(()=>[...t[8]||(t[8]=[e("lkxed",-1)])]),_:1}),t[13]||(t[13]=e(" 译者：",-1)),n(r,{href:"https://github.com/TaivasJumala"},{default:o(()=>[...t[9]||(t[9]=[e("Taivas Jumala",-1)])]),_:1}),t[14]||(t[14]=e(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...t[16]||(t[16]=[e("Linux中国",-1)])]),_:1}),t[19]||(t[19]=e(" 荣誉推出",-1))])])}const P=l(m,[["render",f]]);export{C as __pageData,P as default};
